  $('#resetScenario').addEventListener('click',()=>renderScenario(false));$('#revealQuestion').addEventListener('click',revealCurrentQuestion);$('#listenQuestion').addEventListener('click',()=>speak(currentScenario.q));
  $('#modelLevel').addEventListener('change',()=>{if(!$('#scenarioModel').hidden)renderScenarioModel()});
  function renderScenarioModel(){const l=$('#modelLevel').value,text=currentScenario.models[l];$('#scenarioModel').innerHTML=`<span class="model-level">${esc($('#modelLevel').selectedOptions[0].text)} · model</span><p>${esc(text)}</p>`;$('#scenarioModel').hidden=false}
  $('#revealModel').addEventListener('click',renderScenarioModel);$('#listenModel').addEventListener('click',()=>speak(currentScenario.models[$('#modelLevel').value]));
  function setAnswerTimer(){answerSeconds--;const m=String(Math.floor(answerSeconds/60)).padStart(2,'0'),s=String(answerSeconds%60).padStart(2,'0');$('#answerTimer').textContent=`${m}:${s}`;$('#answerTimer').classList.toggle('warning',answerSeconds<=15);if(answerSeconds<=0){clearInterval(answerTimerInterval);$('#answerTimer').textContent='TIME';}}
  $('#startAnswerTimer').addEventListener('click',()=>{clearInterval(answerTimerInterval);answerSeconds=75;$('#answerTimer').textContent='01:15';answerTimerInterval=setInterval(setAnswerTimer,1000)});
  $('#saveOwnAnswer').addEventListener('click',()=>{const item={id:currentScenario.id,category:currentScenario.label,question:currentScenario.q,cues:[$('#cue1').value,$('#cue2').value,$('#cue3').value].filter(Boolean),answer:$('#scenarioOwnAnswer').value.trim(),checks:$$('[data-selfcheck]').filter(c=>c.checked).map(c=>c.dataset.selfcheck),savedAt:new Date().toLocaleString()};state.scenarioHistory.unshift(item);state.scenarioHistory=state.scenarioHistory.slice(0,30);state.completed.add('scenario-practice');persist();renderHistory();updateReport();$('#saveOwnAnswer').textContent='Saved ✓';setTimeout(()=>$('#saveOwnAnswer').textContent='Save my answer',1200)});
  function renderHistory(){const root=$('#scenarioHistory');if(!state.scenarioHistory.length){root.innerHTML='<p class="feedback">No saved answers yet. Speak first, then save only the notes worth keeping.</p>';return}root.innerHTML=state.scenarioHistory.slice(0,8).map(x=>`<article class="history-card"><small>${esc(x.category)} · ${esc(x.savedAt)}</small><strong>${esc(x.question)}</strong><p><b>Cues:</b> ${esc(x.cues.join(' · ')||'—')}\n<b>Notes:</b> ${esc(x.answer||'—')}\n<b>Self-check:</b> ${esc(x.checks.join(', ')||'—')}</p></article>`).join('')}
  renderHistory();
  function scenarioNotesText(){return ['MAHRIA — FINAL INTERVIEW REHEARSAL NOTES','',...state.scenarioHistory.map((x,i)=>`${i+1}. ${x.question}\nCategory: ${x.category}\nCues: ${x.cues.join(' · ')||'—'}\nOwn answer / notes: ${x.answer||'—'}\nSelf-check: ${x.checks.join(', ')||'—'}\n`)].join('\n')}
  $('#copyScenarioNotes').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(scenarioNotesText());$('#copyScenarioNotes').textContent='Copied ✓';setTimeout(()=>$('#copyScenarioNotes').textContent='Copy notes',1200)}catch{alert('Copy is not available in this browser. Use Download notes instead.')}});
  $('#downloadScenarioNotes').addEventListener('click',()=>downloadText('Mahria-Final-Interview-Rehearsal-Notes.txt',scenarioNotesText()));
  chooseScenario('warmup');

  // Auto-scored grammar
  const grammarQuestions=[
    {id:'g1',q:'Choose the natural sentence about your experience.',choices:[['I have worked in the luxury industry for more than ten years.',true],['I work in the luxury industry since more than ten years.',false],['I have worked on luxury since ten years.',false]],why:'Use present perfect for experience continuing to now, and for + duration.'},
    {id:'g2',q:'Choose the correct interview date phrase.',choices:[["I have an interview on Monday, 24 August.",true],["I have an interview in Monday, 24 August.",false],["I have an interview at Monday, 24 August.",false]],why:'Use on for days and dates.'},
    {id:'g3',q:'Choose the strongest sentence for two urgent priorities.',choices:[["If both directors had urgent requests, I would clarify the impact before prioritising.",true],["If both directors would have urgent requests, I clarify the impact.",false],["If both directors had urgent requests, I will clarified the impact.",false]],why:'Hypothetical: If + past simple → would + base verb.'},
    {id:'g4',q:'Which sentence links action and purpose naturally?',choices:[["I prepared the onboarding schedule so that the new director could become operational quickly.",true],["I prepared the onboarding schedule for the new director can become operational quickly.",false],["I prepared the onboarding schedule because become operational quickly.",false]],why:'Use so that + subject + could/would/can for purpose.'},
    {id:'g5',q:'Choose the natural phrase about a previous employer.',choices:[["At Cartier, I supported a new director during her onboarding.",true],["In Cartier, I supported a new director during her onboarding.",false],["On Cartier, I supported a new director during her onboarding.",false]],why:'Use at + company name when referring to the workplace.'},
    {id:'g6',q:'Choose the professional correction.',choices:[["Let me put that another way.",true],["I explain again me.",false],["I remake my phrase.",false]],why:'“Let me put that another way” is a natural reformulation phrase.'},
    {id:'g7',q:'Choose the strongest result sentence.',choices:[["As a result, she could become operational quickly.",true],["For result, she can operational quickly.",false],["At the result, she became quick operational.",false]],why:'As a result introduces the consequence naturally.'},
    {id:'g8',q:'Choose the natural sentence about adapting to footwear.',choices:[["I do not know every technical term yet, but I know how to learn a new environment quickly.",true],["I do not know yet all technical terms, but I know learn quickly a new environment.",false],["I am not knowing every technical term, but I can to learn fast.",false]],why:'Use know how to + base verb; place yet naturally at the end or after auxiliary verbs.'}
  ];
  function recordAuto(id,isCorrect){state.answers[id]=!!isCorrect;state.attempted[id]=true;persist();updateReport()}
  function renderQuiz(){const root=$('#grammarQuiz');root.innerHTML='';grammarQuestions.forEach(item=>{const card=document.createElement('article');card.className='quiz-card';card.innerHTML=`<p class="q">${esc(item.q)}</p><div class="choice-row"></div><div class="feedback" aria-live="polite"></div>`;const row=$('.choice-row',card),fb=$('.feedback',card);shuffle(item.choices).forEach(([txt,ok])=>{const b=document.createElement('button');b.type='button';b.className='choice-btn';b.textContent=txt;b.addEventListener('click',()=>{if(card.dataset.done)return;card.dataset.done='1';$$('.choice-btn',card).forEach(x=>x.classList.add('dim'));b.classList.remove('dim');b.classList.add(ok?'correct':'incorrect');if(!ok){const correct=[...item.choices].find(x=>x[1])[0];$$('.choice-btn',card).find(x=>x.textContent===correct)?.classList.add('correct')}fb.className='feedback '+(ok?'good':'bad');fb.textContent=(ok?'Correct. ':'Not quite. ')+item.why;recordAuto(item.id,ok)});row.appendChild(b)});root.appendChild(card)})}
  renderQuiz();
