  function renderOrders(){const root=$('#orderGrid');root.innerHTML='';orders.forEach(x=>{const c=document.createElement('article');c.className='order-card';const shuffled=shuffle(x.words.map((w,i)=>({w,i})));c.innerHTML=`<p>Build the sentence:</p><div class="word-bank"></div><div class="order-answer"></div><div class="feedback">Click the words in order. It checks automatically when you use them all.</div>`;const bank=$('.word-bank',c),ans=$('.order-answer',c),fb=$('.feedback',c);let chosen=[];function paint(){bank.innerHTML='';shuffled.forEach((obj,j)=>{const b=document.createElement('button');b.type='button';b.className='word-token'+(chosen.includes(j)?' used':'');b.textContent=obj.w;b.disabled=chosen.includes(j);b.addEventListener('click',()=>{chosen.push(j);paint();check()});bank.appendChild(b)});ans.innerHTML='';chosen.forEach((j,pos)=>{const b=document.createElement('button');b.type='button';b.className='word-token';b.textContent=shuffled[j].w;b.title='Click to remove';b.addEventListener('click',()=>{chosen.splice(pos,1);paint();ans.className='order-answer';fb.className='feedback';fb.textContent='Keep building the sentence.'});ans.appendChild(b)})}function check(){if(chosen.length!==shuffled.length)return;const built=chosen.map(j=>shuffled[j].w).join(' '),ok=norm(built)===norm(x.answer);ans.className='order-answer '+(ok?'correct':'incorrect');fb.className='feedback '+(ok?'good':'bad');fb.textContent=ok?'Correct ✓':'Not quite — click any word in your answer to remove it and try again.';recordAuto(x.id,ok)}paint();root.appendChild(c)})}
  renderOrders();

